import { useEffect, useMemo, useState } from 'react'
import { Link, useParams } from 'react-router'
import { useCanCall } from '@features/permissions/my-permissions'
import { ArrowRight, CheckCircle2, Download, Eye, FileCheck2, GripVertical, LayoutTemplate, Mail, Save, Send, ShieldCheck, Sparkles } from 'lucide-react'
import {
  useComplaintItemsMedia, useComplaintManagers, useComplaintReport, useComplaintReportDownload, useGenerateComplaintReport,
  useSaveComplaintReportDraft, useSendComplaintEmail, useSetComplaintReportStatus,
  reportStatusLabel,
  type ComplaintReportDetail,
} from '@features/complaints'
import { ComplaintEmpty, ComplaintStatusBadge, ComplaintWorkflow } from '../../components/ComplaintUi'
import { ReportCoverPreview, ReportSlidePreview, ReportTablePreview } from '../../components/reportPreview'
import { buildSlidePlan } from '../../components/reportPreviewModel'
import { CoverPicker } from '../../components/CoverPicker'
import { DEFAULT_SLOGAN, coverFor, coverTexts, formatCoverDate, reportTheme, sectorLabelFor, type ComplaintCoverId } from '@lib/pptx/complaintCovers'
import { ExecPageHeader } from '@components/executive/ExecPageHeader'
import { parentSectorLabel, parentSectorTitle } from '@sdk/sectors.sdk'
import { useParentSectors } from '@features/sectors'

const deliveryLabels: Record<string, string> = {
  queued: 'في قائمة الإرسال', accepted: 'قبله مزود البريد', delivered: 'مُسلّم',
  temporary_failure: 'فشل مؤقت', permanent_failure: 'فشل نهائي', rejected: 'مرفوض',
}
const validEmail = (value: string) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)
const triggerDownload = (url: string) => {
  const link = document.createElement('a')
  link.href = url
  link.rel = 'noopener noreferrer'
  link.click()
}

export default function ReportEditorPage() {
  const { id } = useParams()
  const query = useComplaintReport(id ?? null)
  if (query.isLoading) return <div className="h-72 animate-pulse rounded-3xl bg-slate-100" />
  if (query.isError) return <ComplaintEmpty icon={LayoutTemplate} title="تعذر تحميل التقرير" description="تحقق من الاتصال والصلاحيات ثم أعد المحاولة؛ لم يتم عرض نسخة ناقصة." />
  if (!query.data) return <ComplaintEmpty icon={LayoutTemplate} title="التقرير غير موجود" description="قد يكون التقرير مؤرشفاً أو أن الرابط غير صحيح." />
  return <Editor key={query.data.id} initial={query.data} />
}

function Editor({ initial }: { initial: ComplaintReportDetail }) {
  const { parents: sectorParents } = useParentSectors()   // 00395
  const [title, setTitle] = useState(initial.title)
  const [layout, setLayout] = useState(initial.layout)
  const [recipients, setRecipients] = useState(initial.recipients.join('\n'))
  const [items, setItems] = useState(initial.items)
  const [dragged, setDragged] = useState<number | null>(null)
  const [message, setMessage] = useState('')
  const [dirty, setDirty] = useState(false)
  const [preview, setPreview] = useState<'cover' | 'table' | 'slides'>('cover')
  const [previewItem, setPreviewItem] = useState(0)
  const [reviewConfirmed, setReviewConfirmed] = useState(false)

  const save = useSaveComplaintReportDraft()
  const generate = useGenerateComplaintReport()
  const approve = useSetComplaintReportStatus()
  const canApprove = useCanCall('complaint_approve_report')
  const download = useComplaintReportDownload()
  const send = useSendComplaintEmail()
  const managers = useComplaintManagers().data ?? []
  const managerNames = new Map(managers.map(manager => [manager.userId, manager.fullName]))
  const includedItems = items.filter(item => item.included)
  const media = useComplaintItemsMedia(includedItems.map(item => item.itemId))
  const reportGroups = new Map<string, { subject: string; manager: string; count: number }>()
  for (const entry of includedItems) {
    const key = `${entry.item.inboxMessageId ?? entry.item.complaintId}:${entry.item.assignedTo ?? 'unassigned'}`
    const current = reportGroups.get(key) ?? { subject: entry.item.ticketName || 'بريد دون موضوع', manager: managerNames.get(entry.item.assignedTo ?? '') ?? 'مسؤول القسم', count: 0 }
    current.count += 1
    reportGroups.set(key, current)
  }

  useEffect(() => {
    setTitle(initial.title)
    setLayout(initial.layout)
    setRecipients(initial.recipients.join('\n'))
    setItems(initial.items)
    setDirty(false)
    setReviewConfirmed(false)
  }, [initial])

  useEffect(() => {
    const warn = (event: BeforeUnloadEvent) => {
      if (!dirty) return
      event.preventDefault()
    }
    window.addEventListener('beforeunload', warn)
    return () => window.removeEventListener('beforeunload', warn)
  }, [dirty])

  const emails = useMemo(() => [...new Set(recipients.split(/[\n,;]+/).map(value => value.trim().toLowerCase()).filter(Boolean))], [recipients])
  const invalidEmails = emails.filter(email => !validEmail(email))
  const editable = ['draft', 'quality_review', 'failed'].includes(initial.status)
  const theme = reportTheme(layout)
  const accent = theme.primary
  const cover = coverFor(layout)
  const liveTexts = coverTexts(layout, { sector: initial.sector, reportDate: initial.reportDate })
  const payload = { id: initial.id, title: title.trim(), layout, recipients: emails, items }
  const canSave = editable && Boolean(title.trim()) && emails.length > 0 && invalidEmails.length === 0 && includedItems.length > 0
  const canGenerate = editable && Boolean(title.trim()) && includedItems.length > 0

  const changeLayout = (key: string, value: unknown) => { setLayout(old => ({ ...old, [key]: value })); setDirty(true) }
  const move = (from: number, to: number) => {
    if (to < 0 || to >= items.length) return
    setItems(old => {
      const next = [...old]; const [picked] = next.splice(from, 1); if (!picked) return old
      next.splice(to, 0, picked); return next.map((value, index) => ({ ...value, displayOrder: index + 1 }))
    }); setDirty(true)
  }
  const saveNow = () => {
    if (!canSave) { setMessage('أكمل عنوان التقرير والمستلمين الصحيحين واختر موقعاً واحداً على الأقل.'); return }
    save.mutate(payload, { onSuccess: () => { setDirty(false); setMessage('تم حفظ تصميم التقرير وترتيب المواقع.') }, onError: () => setMessage('تعذر حفظ التعديلات؛ راجع العنوان والمستلمين.') })
  }
  const runGenerate = () => generate.mutate(initial.id, {
    onSuccess: () => { setDirty(false); setMessage('تم توليد PowerPoint وأصبح جاهزاً للمراجعة.') },
    onError: () => setMessage('تعذر توليد PowerPoint؛ تأكد من تضمين موقع واحد على الأقل.'),
  })
  const generateNow = () => {
    if (!canGenerate) { setMessage('لا يمكن التوليد دون عنوان وموقع واحد مضمن على الأقل.'); return }
    if (dirty && canSave) save.mutate(payload, { onSuccess: runGenerate, onError: () => setMessage('تعذر حفظ التعديلات، لذلك أُلغي التوليد حتى لا يُنشأ ملف قديم.') })
    else if (dirty) setMessage('صحح بيانات المستلمين أولاً حتى يمكن حفظ التصميم المعدل قبل التوليد.')
    else runGenerate()
  }

  const slideEntry = includedItems[Math.min(previewItem, Math.max(0, includedItems.length - 1))]
  const before = media.data?.find(value => value.itemId === slideEntry?.itemId && value.kind === 'before')
  const after = media.data?.find(value => value.itemId === slideEntry?.itemId && value.kind === 'after')
  const slidePlan = buildSlidePlan(includedItems)
  const readyChecks = [
    { label: 'عنوان التقرير', ok: Boolean(title.trim()) },
    { label: 'موقع واحد على الأقل', ok: includedItems.length > 0 },
    { label: 'المستلمون صالحون', ok: emails.length > 0 && invalidEmails.length === 0 },
    { label: 'ملف PowerPoint مولّد', ok: Boolean(initial.pptxPath) },
  ]

  return <section className="min-h-full space-y-5 pb-8" dir="rtl">
    <ExecPageHeader icon="edit" title="محرر التقرير والمراجعة" subtitle={<><span className="font-bold text-[#f3d06a]">{initial.scope === 'email' ? 'تقرير بريد مستقل' : 'تقرير يومي جامع'}</span> · {initial.reportDate} · {parentSectorTitle(initial.sector)} · {reportStatusLabel(initial.status)}</>} actions={<>
      <Link to="/complaints/templates" className="inline-flex h-9 items-center gap-1 rounded-xl bg-white/10 px-3 text-xs font-black text-white ring-1 ring-white/25 hover:bg-white/20"><ArrowRight size={15} />العودة إلى التقارير</Link><span className={`rounded-full px-4 py-2 text-xs font-black ${dirty ? 'bg-amber-400 text-amber-950' : 'bg-white/10 text-white'}`}>{dirty ? 'تعديلات غير محفوظة' : 'النسخة محفوظة'}</span>
    </>} />
    <ComplaintWorkflow current="report" />

    <div className="grid gap-2 rounded-2xl border bg-white p-2 shadow-sm sm:grid-cols-4">{[
      ['1', 'التصميم والترتيب', editable], ['2', 'إنشاء ملف العرض', Boolean(initial.pptxPath)], ['3', 'المراجعة والاعتماد', ['approved', 'sending', 'sent', 'archived'].includes(initial.status)], ['4', 'الإرسال والتسليم', ['sent', 'archived'].includes(initial.status)],
    ].map(([number, label, complete]) => <div key={String(number)} className={`rounded-xl p-3 text-xs font-bold ${complete ? 'bg-emerald-50 text-emerald-800' : 'bg-slate-50 text-slate-500'}`}><span className="ml-2 inline-flex size-6 items-center justify-center rounded-full bg-white">{complete ? <CheckCircle2 size={14} /> : number}</span>{label}</div>)}</div>

    {initial.approvalRejectedNote && initial.status === 'quality_review' && !initial.approvalChainId && <p className="rounded-2xl border border-red-200 bg-red-50 p-4 text-sm font-bold text-red-900" data-testid="report-rejected-note">أُعيد التقرير من سلسلة الموافقات — السبب: {initial.approvalRejectedNote}. عالج الملاحظة ثم أعد التوليد والاعتماد.</p>}
    {message && <p aria-live="polite" className="rounded-2xl border border-blue-100 bg-blue-50 p-4 text-sm font-bold text-blue-900">{message}</p>}

    <div className="sticky top-2 z-20 flex flex-wrap gap-2 rounded-2xl border border-slate-200 bg-white/95 p-3 shadow-lg backdrop-blur">
      {editable && <button onClick={saveNow} disabled={save.isPending || !canSave} className="inline-flex items-center gap-2 rounded-xl bg-slate-800 px-4 py-2.5 text-sm font-bold text-white disabled:opacity-40"><Save size={17} />حفظ التصميم</button>}
      {editable && <button disabled={generate.isPending || save.isPending || !canGenerate} onClick={generateNow} className="inline-flex items-center gap-2 rounded-xl bg-blue-700 px-4 py-2.5 text-sm font-bold text-white disabled:opacity-40"><Sparkles size={17} />توليد PowerPoint</button>}
      {initial.pptxPath && <button disabled={download.isPending} onClick={() => download.mutate(initial.pptxPath!, { onSuccess: triggerDownload, onError: () => setMessage('تعذر تجهيز رابط تنزيل PowerPoint؛ أعد المحاولة.') })} className="inline-flex items-center gap-2 rounded-xl border px-4 py-2.5 text-sm font-bold disabled:opacity-40"><Download size={17} />تنزيل ومراجعة</button>}
      {initial.status === 'quality_review' && initial.approvalChainId && <span className="inline-flex items-center gap-2 rounded-xl border border-amber-300 bg-amber-50 px-4 py-2.5 text-sm font-bold text-amber-900" data-testid="report-chain-pending"><ShieldCheck size={17} />بانتظار سلسلة الموافقات — ستصلك النتيجة إشعاراً</span>}
      {initial.status === 'quality_review' && !initial.approvalChainId && <button disabled={approve.isPending || !reviewConfirmed || !initial.pptxPath || !canApprove.allowed} title={canApprove.title} onClick={() => approve.mutate({ reportId: initial.id, status: 'approved', reviewedPptxPath: initial.pptxPath ?? undefined }, { onSuccess: () => setMessage('تم تسجيل الاعتماد — إن كانت هناك سلسلة موافقات مضبوطة فسيُعتمد التقرير بعد اكتمالها.'), onError: () => setMessage('تعذر الاعتماد؛ يشترط ملف PowerPoint مولّد وتأكيد المراجعة.') })} className="inline-flex items-center gap-2 rounded-xl bg-emerald-700 px-4 py-2.5 text-sm font-bold text-white disabled:opacity-40"><ShieldCheck size={17} />اعتماد التقرير</button>}
      {['approved', 'failed'].includes(initial.status) && initial.pptxPath && <button disabled={!emails.length || invalidEmails.length > 0 || send.isPending} onClick={() => send.mutate({ reportId: initial.id, to: emails, subject: title, text: `السلام عليكم، مرفق ${title}`, attachmentPaths: [initial.pptxPath!] }, { onSuccess: () => setMessage(initial.status === 'failed' ? 'قُبلت إعادة محاولة الإرسال، وستظهر نتيجتها في سجل التسليم.' : 'قُبل طلب الإرسال، وسيتم تحديث حالة التسليم تلقائياً.'), onError: () => setMessage('تعذر الإرسال؛ تحقق من إعداد Mailgun والمستلمين المعتمدين ثم أعد المحاولة.') })} className="inline-flex items-center gap-2 rounded-xl bg-rose-700 px-4 py-2.5 text-sm font-bold text-white disabled:opacity-40"><Send size={17} />{initial.status === 'failed' ? 'إعادة محاولة الإرسال' : 'إرسال إلى الجهة المرسلة'}</button>}
    </div>

    <div className="grid items-start gap-5 xl:grid-cols-[330px_minmax(0,1fr)]">
      <aside className="space-y-4 xl:sticky xl:top-24">
        <article className="rounded-2xl border bg-white p-5 shadow-sm"><div className="flex items-center gap-2"><LayoutTemplate className="text-indigo-700" size={19} /><h2 className="font-black">هوية الشرائح</h2></div>
          <label className="mt-4 block text-xs font-bold">عنوان التقرير<input disabled={!editable} value={title} onChange={event => { setTitle(event.target.value); setDirty(true) }} className="mt-1 w-full rounded-xl border p-2.5 text-sm" /></label>
                    <CoverPicker value={cover.id} disabled={!editable} onChange={(id: ComplaintCoverId) => changeLayout('cover', id)} />
          {cover.id === 'official' && <label className="mt-3 flex items-center justify-between text-xs font-bold">اللون الرئيسي<input disabled={!editable} type="color" value={accent.toLowerCase()} onChange={event => changeLayout('accent', event.target.value)} /></label>}
          <label className="mt-3 block text-xs font-bold">عنوان الغلاف<input disabled={!editable} value={String(layout.title ?? 'تقرير معالجة التلكؤات ليوم')} onChange={event => changeLayout('title', event.target.value)} className="mt-1 w-full rounded-xl border p-2.5" /></label>
          <label className="mt-3 block text-xs font-bold">سطر القاطع على الغلاف<input disabled={!editable} aria-label="سطر القاطع على الغلاف" value={liveTexts.sectorLine} onChange={event => changeLayout('coverSectorLine', event.target.value)} className="mt-1 w-full rounded-xl border p-2.5" /><span className="mt-1 flex gap-1">{sectorParents.map(({ code }) => <button key={code} type="button" disabled={!editable} onClick={() => changeLayout('coverSectorLine', sectorLabelFor(code))} className={`rounded-lg border px-2 py-1 text-[10px] font-bold ${liveTexts.sectorLine === sectorLabelFor(code) ? 'border-indigo-600 bg-indigo-50 text-indigo-800' : 'text-slate-600'}`}>{sectorLabelFor(code)}</button>)}</span></label>
          <div className="mt-3 rounded-xl border p-2"><span className="text-xs font-bold">أرقام التاريخ على الغلاف</span><div className="mt-1 flex gap-1">{([['latin', 'لاتينية 2026/10/2'], ['arabic', 'عربية ٢٠٢٦/١٠/٢']] as const).map(([digits, text]) => <button key={digits} type="button" disabled={!editable} onClick={() => { changeLayout('coverDateDigits', digits); changeLayout('coverDateText', '') }} className={`rounded-lg border px-2 py-1 text-[10px] font-bold ${(layout.coverDateDigits ?? 'latin') === digits ? 'border-indigo-600 bg-indigo-50 text-indigo-800' : 'text-slate-600'}`}>{text}</button>)}</div>
            <label className="mt-2 block text-xs font-bold">نص التاريخ<input disabled={!editable} aria-label="نص التاريخ على الغلاف" value={liveTexts.dateLine} onChange={event => changeLayout('coverDateText', event.target.value)} className="mt-1 w-full rounded-xl border p-2" /><span className="text-[10px] font-normal text-slate-500">الافتراضي: {formatCoverDate(initial.reportDate, layout.coverDateDigits === 'arabic' ? 'arabic' : 'latin')}</span></label></div>
          <label className="mt-3 block text-xs font-bold">الشعار أسفل الغلاف<input disabled={!editable} aria-label="شعار الغلاف" value={typeof layout.coverSlogan === 'string' ? layout.coverSlogan : DEFAULT_SLOGAN} onChange={event => changeLayout('coverSlogan', event.target.value)} placeholder="اتركه فارغاً لإخفائه" className="mt-1 w-full rounded-xl border p-2.5" /></label>
          <label className="mt-3 block text-xs font-bold">الجهة الحكومية<input disabled={!editable} value={String(layout.authorityLine ?? `أمانة بغداد / دائرة بلدية ${parentSectorLabel(initial.sector)}`)} onChange={event => changeLayout('authorityLine', event.target.value)} className="mt-1 w-full rounded-xl border p-2.5" /></label>
          <label className="mt-3 block text-xs font-bold">الجهة المنفذة<input disabled={!editable} value={String(layout.contractorLine ?? 'تحالف شركات جزيرة الأكارم وفيرست ترايد')} onChange={event => changeLayout('contractorLine', event.target.value)} className="mt-1 w-full rounded-xl border p-2.5" /></label>
          <div className="grid grid-cols-2 gap-2"><label className="mt-3 text-xs font-bold">عنوان قبل<input disabled={!editable} value={String(layout.beforeLabel ?? 'صورة التلكؤ / الشكوى')} onChange={event => changeLayout('beforeLabel', event.target.value)} className="mt-1 w-full rounded-xl border p-2" /></label><label className="mt-3 text-xs font-bold">عنوان بعد<input disabled={!editable} value={String(layout.afterLabel ?? 'صورة المعالجة')} onChange={event => changeLayout('afterLabel', event.target.value)} className="mt-1 w-full rounded-xl border p-2" /></label></div>
          <label className="mt-3 block text-xs font-bold">الخط<select disabled={!editable} value={String(layout.fontFamily ?? 'Arial')} onChange={event => changeLayout('fontFamily', event.target.value)} className="mt-1 w-full rounded-xl border p-2.5"><option>Arial</option><option>Tahoma</option><option>Calibri</option></select></label>
          <label className="mt-3 block text-xs font-bold">حجم عنوان الغلاف: {Number(layout.coverFontSize ?? 30)}<input disabled={!editable} type="range" min="20" max="42" value={Number(layout.coverFontSize ?? 30)} onChange={event => changeLayout('coverFontSize', Number(event.target.value))} className="mt-2 w-full" /></label>
          <label className="mt-3 block text-xs font-bold">ارتفاع الصور: {Number(layout.imageHeight ?? 4.8).toFixed(1)}<input disabled={!editable} type="range" min="3" max="4.8" step="0.1" value={Number(layout.imageHeight ?? 4.8)} onChange={event => changeLayout('imageHeight', Number(event.target.value))} className="mt-2 w-full" /></label>
        </article>
        <article className="rounded-2xl border bg-white p-5 shadow-sm"><div className="flex items-center gap-2"><Mail className="text-indigo-700" size={19} /><h2 className="font-black">المستلمون</h2></div><label className="mt-3 block text-xs font-bold">البريد الأصلي وأي بريد إضافي<textarea disabled={!editable} value={recipients} onChange={event => { setRecipients(event.target.value); setDirty(true) }} placeholder="سطر مستقل لكل بريد" className="mt-2 min-h-28 w-full rounded-xl border p-3" /></label>{invalidEmails.length > 0 && <p className="mt-2 text-xs font-bold text-red-700">عناوين غير صحيحة: {invalidEmails.join('، ')}</p>}</article>
        <article className="rounded-2xl border bg-white p-5 shadow-sm"><h2 className="font-black">جاهزية التقرير</h2><ul className="mt-3 space-y-2">{readyChecks.map(check => <li key={check.label} className={`flex items-center gap-2 text-xs font-bold ${check.ok ? 'text-emerald-700' : 'text-slate-400'}`}>{check.ok ? <CheckCircle2 size={16} /> : <FileCheck2 size={16} />}{check.label}</li>)}</ul></article>
      </aside>

      <main className="space-y-5">
        <article className="rounded-3xl border bg-slate-100 p-4 shadow-inner sm:p-6"><div className="flex flex-wrap items-center justify-between gap-3"><div className="flex items-center gap-2"><Eye className="text-indigo-700" /><div><h2 className="font-black">المعاينة البصرية</h2><p className="text-xs text-slate-500">تمثيل قريب من شرائح PowerPoint قبل التوليد.</p></div></div><div className="flex rounded-xl bg-white p-1">{(['cover', 'table', 'slides'] as const).map(value => <button key={value} onClick={() => setPreview(value)} className={`rounded-lg px-3 py-2 text-xs font-bold ${preview === value ? 'bg-indigo-700 text-white' : 'text-slate-600'}`}>{value === 'cover' ? 'الغلاف' : value === 'table' ? 'الجدول' : 'قبل / بعد'}</button>)}</div></div>
          <div className="mx-auto mt-5 aspect-video w-full max-w-4xl overflow-hidden rounded-xl border bg-white shadow-xl" style={{ borderColor: accent }}>
            {preview === 'cover' && <ReportCoverPreview layout={layout} title={title} accent={accent} sector={initial.sector} reportDate={initial.reportDate} />}
            {preview === 'table' && <ReportTablePreview entries={includedItems} accent={accent} layout={layout} />}
            {preview === 'slides' && <ReportSlidePreview entry={slideEntry} before={before?.url} after={after?.url} accent={accent} layout={layout} />}
          </div>
          <details className="mx-auto mt-4 w-full max-w-4xl rounded-xl border bg-white p-3"><summary className="cursor-pointer text-xs font-black text-slate-600">ترتيب شرائح ملف PowerPoint الناتج ({slidePlan.length} شريحة) — مطابق للمعاينة أعلاه</summary><div className="mt-3 flex flex-wrap gap-1.5">{slidePlan.map((step, index) => <span key={`${step.kind}-${index}`} className={`rounded-full border px-2.5 py-1 text-[10px] font-bold ${step.kind === 'cover' ? 'border-fuchsia-200 bg-fuchsia-50 text-fuchsia-800' : step.kind === 'table' ? 'border-sky-200 bg-sky-50 text-sky-800' : 'border-emerald-200 bg-emerald-50 text-emerald-800'}`}>{step.label}</span>)}</div></details>
          {preview === 'slides' && includedItems.length > 1 && <div className="mt-4 flex items-center justify-center gap-3"><button onClick={() => setPreviewItem(Math.max(0, previewItem - 1))} disabled={previewItem === 0} className="rounded-lg border bg-white px-3 py-2 text-xs font-bold disabled:opacity-40">السابق</button><span className="text-xs font-bold">الموقع {previewItem + 1} من {includedItems.length}</span><button onClick={() => setPreviewItem(Math.min(includedItems.length - 1, previewItem + 1))} disabled={previewItem >= includedItems.length - 1} className="rounded-lg border bg-white px-3 py-2 text-xs font-bold disabled:opacity-40">التالي</button></div>}
        </article>

        <article className="rounded-3xl border bg-white p-5 shadow-sm"><div className="flex flex-wrap justify-between gap-2"><div><h2 className="font-black">ترتيب ومحتوى التقرير</h2><p className="mt-1 text-xs text-slate-500">السحب أو الأسهم يعيدان ترتيب الشرائح. الاستبعاد لا يحذف بيانات الموقع.</p></div><span className="rounded-xl bg-slate-100 px-3 py-2 text-xs font-bold">{includedItems.length} من {items.length} موقع</span></div>
          <div className="mt-4 grid gap-2 sm:grid-cols-2">{[...reportGroups.entries()].map(([key, group]) => <div key={key} className="rounded-xl border border-indigo-100 bg-indigo-50 p-3"><p className="truncate text-xs font-black text-indigo-950">{group.subject}</p><p className="mt-1 text-[11px] text-indigo-700">{group.manager} · {group.count} موقع</p></div>)}</div>
          <p className="mt-4 rounded-xl bg-slate-50 p-3 text-xs font-bold text-slate-600">يحافظ PowerPoint على ترتيب المواقع كما في المعاينة: غلاف، جدول البيانات، ثم شريحة قبل/بعد لكل موقع.</p>
          <div className="mt-3 space-y-2">{items.map((entry, index) => <div key={entry.itemId} draggable={editable} onDragStart={() => setDragged(index)} onDragOver={event => event.preventDefault()} onDrop={() => { if (dragged !== null) move(dragged, index); setDragged(null) }} className={`flex flex-wrap items-center gap-3 rounded-2xl border p-3 ${entry.included ? 'bg-white' : 'bg-slate-100 opacity-60'}`}>
            <GripVertical className="cursor-grab text-slate-400" size={18} /><input aria-label={`تضمين الموقع ${entry.item.sequenceNo}`} disabled={!editable} type="checkbox" checked={entry.included} onChange={event => { setItems(old => old.map(value => value.itemId === entry.itemId ? { ...value, included: event.target.checked } : value)); setDirty(true) }} />
            <div className="min-w-0 flex-1"><Link to={`/complaints/items/${entry.itemId}`} className="font-black text-blue-700">{entry.item.referenceNo} / {entry.item.sequenceNo}</Link><p className="truncate text-xs text-slate-500">محلة {entry.item.neighborhood || '—'} · زقاق {entry.item.alley || '—'} · {entry.item.title || 'نوع غير محدد'}</p><p className="mt-1 truncate text-[11px] font-bold text-indigo-700">{entry.item.ticketName || 'بريد دون موضوع'} · {managerNames.get(entry.item.assignedTo ?? '') ?? 'مسؤول القسم'}</p></div><ComplaintStatusBadge status={entry.item.status} />
            <button disabled={!editable || index === 0} onClick={() => move(index, index - 1)} aria-label="تحريك للأعلى" className="rounded-lg border px-2 py-1">↑</button><button disabled={!editable || index === items.length - 1} onClick={() => move(index, index + 1)} aria-label="تحريك للأسفل" className="rounded-lg border px-2 py-1">↓</button>
          </div>)}</div>
        </article>

        {initial.status === 'quality_review' && !initial.approvalChainId && <label className="flex cursor-pointer items-start gap-3 rounded-2xl border border-emerald-200 bg-emerald-50 p-4 text-sm font-bold text-emerald-900"><input type="checkbox" checked={reviewConfirmed} onChange={event => setReviewConfirmed(event.target.checked)} className="mt-1 size-5" /><span>نزّلت ملف PowerPoint وراجعت الغلاف والجدول وكل صور قبل/بعد والمستلمين. أفهم أن الاعتماد يقفل التصميم للإرسال.</span></label>}
      </main>
    </div>

    <article className="rounded-3xl border bg-white p-5 shadow-sm"><h2 className="font-black">سجل محاولات التسليم</h2>{!initial.deliveries.length ? <p className="mt-3 text-sm text-slate-500">لم تبدأ أي محاولة إرسال لهذا التقرير.</p> : <div className="mt-3 overflow-x-auto"><table className="w-full min-w-[650px] text-sm"><thead><tr className="bg-slate-50"><th className="p-3 text-right">الوقت</th><th className="p-3 text-right">المستلمون</th><th className="p-3">الحالة</th><th className="p-3 text-right">النتيجة</th></tr></thead><tbody>{initial.deliveries.map(delivery => <tr key={delivery.id} className="border-t"><td className="p-3">{new Date(delivery.createdAt).toLocaleString('ar-IQ-u-nu-latn')}</td><td className="p-3" dir="ltr">{delivery.recipients.join(', ')}</td><td className="p-3 text-center font-bold">{deliveryLabels[delivery.status] ?? delivery.status}</td><td className="p-3">{delivery.errorMessage ?? (delivery.deliveredAt ? `تم التسليم ${new Date(delivery.deliveredAt).toLocaleString('ar-IQ-u-nu-latn')}` : 'بانتظار تحديث مزود البريد')}</td></tr>)}</tbody></table></div>}</article>
  </section>
}
